insert into public.content_items (id, title, slug, subtitle, description, subject_id, topic_id, content_type, difficulty, price_minor_units, currency, is_free, subscription_eligible, estimated_reading_minutes, byline, learning_objectives, pdf_downloadable, featured) values ('30000000-0000-4000-8000-000000000002', 'The Cell Membrane and Transport Mechanisms', 'cell-membrane-transport', 'How substances cross the plasma membrane, and what it costs', 'Fluid mosaic model, diffusion, carriers, pumps and vesicles. A clear foundation for physiology and pharmacology.', '10000000-0000-4000-8000-000000000004', '20000000-0000-4000-8000-000000000004', 'study_note', 'beginner', 0, 'INR', true, false, 3, 'StudySimplify Editorial (sample content)', array['Describe the fluid mosaic model of the plasma membrane.', 'Distinguish passive from active transport.', 'Explain primary and secondary active transport with examples.', 'State the factors that affect the rate of simple diffusion.']::text[], false, false) on conflict (id) do nothing;
