insert into public.content_versions (id, content_item_id, version_number, structured_content, change_summary) values ('40000000-0000-4000-8000-000000000001', '30000000-0000-4000-8000-000000000001', 1, '{"schemaVersion":1,"subtitle":"Two questions classify almost every epithelium you will see","overview":"Epithelium is the tissue that covers body surfaces, lines cavities and tubes, and forms glands. Classifying it comes down to two questions: how many layers are there, and what shape are the cells at the surface?","learningObjectives":["List the defining features of epithelial tissue.","Classify an epithelium by number of layers and shape of surface cells.","Give one typical location for each type of epithelium.","Explain why pseudostratified epithelium is not truly stratified."],"prerequisites":["Basic cell structure (nucleus, cytoplasm, plasma membrane)."],"references":[{"id":"ross","citation":"Ross MH, Pawlina W. Histology: A Text and Atlas. Wolters Kluwer."},{"id":"junqueira","citation":"Mescher AL. Junqueira''s Basic Histology: Text and Atlas. McGraw Hill."}],"sections":[{"id":"overview","title":"What makes a tissue epithelial?","kind":"overview","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"Epithelia are sheets of closely packed cells with very little extracellular material between them. They form the boundary between the body and its environment: the skin surface, the lining of the gut, the airways and the inside of blood vessels."},{"type":"list","ordered":false,"items":["**Cellularity** – cells are tightly packed and joined by cell junctions.","**Polarity** – each cell has an *apical* (free) surface and a *basal* surface.","**Basement membrane** – the basal surface rests on a supporting basement membrane.","**Avascularity** – epithelium has no blood vessels of its own; it is nourished by diffusion from underlying connective tissue.","**Regeneration** – most epithelia are renewed continuously by cell division."]},{"type":"explainer","technical":"Epithelium is avascular; oxygen and nutrients reach it by diffusion across the basement membrane from capillaries in the underlying lamina propria or dermis.","simplified":"Epithelium has no blood vessels inside it. It gets its supplies from the tissue just underneath, which is why it is usually thin enough for diffusion to work."}]},{"id":"classification","title":"Classification from first principles","kind":"first-principles","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"Ask two questions, in this order:"},{"type":"diagram","title":"Naming an epithelium","layout":"flow","steps":[{"label":"Count the layers","detail":"One layer = simple. More than one = stratified."},{"label":"Look at the surface cells","detail":"Flat = squamous, as tall as wide = cuboidal, taller than wide = columnar."},{"label":"Add special features","detail":"Cilia, microvilli (brush border), keratin, goblet cells."},{"label":"Combine the words","detail":"e.g. stratified squamous keratinised epithelium."}]},{"type":"callout","variant":"tip","title":"Stratified epithelia are named by the top layer","text":"In stratified epithelium the deeper cells are often cuboidal or polygonal. Only the shape of the **surface** layer gives the name."}]},{"id":"types","title":"Types and where to find them","kind":"comparisons","depth":"detailed","preview":false,"blocks":[{"type":"table","caption":"Common epithelia, a typical location and the function the structure suits","headers":["Epithelium","Typical locations","Function suited to structure"],"rows":[["Simple squamous","Lung alveoli, endothelium of vessels, mesothelium","Diffusion and filtration across a thin barrier"],["Simple cuboidal","Kidney tubules, thyroid follicles, small ducts","Secretion and absorption"],["Simple columnar","Stomach, small and large intestine, gallbladder","Absorption and secretion; may carry microvilli"],["Pseudostratified ciliated columnar","Trachea and bronchi","Moves mucus with cilia; goblet cells secrete mucus"],["Stratified squamous keratinised","Epidermis of skin","Protection against abrasion and water loss"],["Stratified squamous non-keratinised","Oral cavity, oesophagus, vagina","Protection of moist surfaces"],["Stratified cuboidal","Ducts of sweat glands","Protection; limited secretion"],["Transitional (urothelium)","Ureters and urinary bladder","Stretches as the bladder fills"]]},{"type":"definition","term":"Pseudostratified epithelium","definition":"A single layer of cells in which every cell rests on the basement membrane, but not every cell reaches the apical surface. Nuclei lie at different heights, so the layer looks stratified.","simplified":"It is one layer that only looks like several layers."}]},{"id":"misconceptions","title":"Common misconceptions","kind":"misconceptions","depth":"mistake","preview":false,"blocks":[{"type":"callout","variant":"mistake","title":"\"Pseudostratified means many layers\"","text":"It is a **simple** epithelium. Look for whether every cell touches the basement membrane, not at how many rows of nuclei you see."},{"type":"callout","variant":"mistake","title":"\"Stratified squamous means every cell is flat\"","text":"Only the surface cells are flat. The basal layer is cuboidal to columnar and is where cell division happens."}]},{"id":"high-yield","title":"High-yield revision points","kind":"high-yield","depth":"exam","preview":false,"blocks":[{"type":"list","ordered":false,"items":["Classification = number of layers + shape of the **surface** cells.","Epithelium is avascular and rests on a basement membrane.","Respiratory epithelium = pseudostratified ciliated columnar with goblet cells.","Urinary bladder = transitional epithelium (urothelium).","Skin = stratified squamous keratinised; oesophagus = non-keratinised."]}]},{"id":"mcqs","title":"Practice MCQs","kind":"practice-mcqs","depth":"exam","preview":false,"blocks":[{"type":"mcq","question":"Which epithelium lines the lumen of the trachea?","options":["Simple squamous","Stratified squamous non-keratinised","Pseudostratified ciliated columnar","Transitional"],"answerIndex":2,"explanation":"The trachea is lined by respiratory epithelium: pseudostratified ciliated columnar epithelium with goblet cells. Cilia move the mucus layer towards the pharynx."},{"type":"mcq","question":"A tissue section shows a single layer of flat cells lining a capillary. What is it called?","options":["Mesothelium","Endothelium","Urothelium","Simple cuboidal epithelium"],"answerIndex":1,"explanation":"The simple squamous epithelium lining blood vessels is called endothelium. Mesothelium is the simple squamous lining of serous cavities such as the pleura and peritoneum."}]},{"id":"oral","title":"Oral examination questions","kind":"oral-questions","depth":"exam","preview":false,"blocks":[{"type":"question","kind":"oral","question":"How is epithelium nourished if it has no blood vessels?","answer":"By diffusion of oxygen and nutrients from capillaries in the underlying connective tissue, across the basement membrane."},{"type":"question","kind":"oral","question":"Why is the bladder lined by transitional epithelium?","answer":"Transitional epithelium can change its appearance as the bladder fills and empties. The surface cells flatten when the bladder is stretched, so the lining can accommodate large changes in volume while staying a barrier to urine."}]},{"id":"summary","title":"Quick revision summary","kind":"summary","depth":"basic","preview":false,"blocks":[{"type":"paragraph","text":"Epithelium is a polarised, avascular sheet of cells on a basement membrane. Name it by counting layers (simple or stratified) and looking at the shape of the surface cells (squamous, cuboidal or columnar), then add special features such as cilia or keratin. Pseudostratified is a single layer that only appears layered; transitional epithelium is the stretchable lining of the urinary tract."}]}]}'::jsonb, 'Initial sample version') on conflict (id) do nothing;
insert into public.content_versions (id, content_item_id, version_number, structured_content, change_summary) values ('40000000-0000-4000-8000-000000000002', '30000000-0000-4000-8000-000000000002', 1, '{"schemaVersion":1,"subtitle":"How substances cross the plasma membrane, and what it costs","overview":"The plasma membrane separates the inside of the cell from its surroundings. It lets some substances through freely, others only through specific proteins, and some only when the cell spends energy.","learningObjectives":["Describe the fluid mosaic model of the plasma membrane.","Distinguish passive from active transport.","Explain primary and secondary active transport with examples.","State the factors that affect the rate of simple diffusion."],"prerequisites":["Concentration gradients","Basic idea of ATP as the energy currency of the cell."],"references":[{"id":"guyton","citation":"Hall JE, Hall ME. Guyton and Hall Textbook of Medical Physiology. Elsevier."},{"id":"alberts","citation":"Alberts B, et al. Molecular Biology of the Cell. W. W. Norton."}],"sections":[{"id":"structure","title":"Structure: the fluid mosaic model","kind":"overview","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"The membrane is a **phospholipid bilayer**. Each phospholipid is *amphipathic*: it has a water-loving (hydrophilic) head and water-fearing (hydrophobic) fatty acid tails. In water the tails face inwards and the heads face the fluid on either side."},{"type":"list","ordered":false,"items":["**Integral proteins** span the bilayer and form channels, carriers and pumps.","**Peripheral proteins** attach to one surface and often act as enzymes or anchors.","**Cholesterol** sits between phospholipids and stabilises fluidity across temperatures.","**Carbohydrates** attached to proteins and lipids on the outer surface form the *glycocalyx*, which is involved in cell recognition."]},{"type":"explainer","technical":"The fluid mosaic model describes the membrane as a two-dimensional fluid of lipids in which proteins are embedded and can diffuse laterally.","simplified":"Think of the membrane as a thin film of oil floating on water, with proteins bobbing in it like boats that can drift sideways."}]},{"id":"passive","title":"Passive transport","kind":"first-principles","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"Passive transport moves substances **down** their electrochemical gradient. It needs no metabolic energy."},{"type":"definition","term":"Simple diffusion","definition":"Movement of molecules directly through the lipid bilayer or through open channels, down a concentration gradient, without binding to a carrier.","simplified":"Molecules spread from where there are more of them to where there are fewer."},{"type":"paragraph","text":"Small lipid-soluble molecules such as O~2~, CO~2~ and many anaesthetic gases cross the bilayer easily. Ions such as Na^+^ and K^+^ need protein channels."},{"type":"equation","latex":"J = -D \\, A \\, \\frac{\\Delta C}{\\Delta x}","fallbackText":"J = −D × A × (ΔC / Δx)","caption":"Fick''s law: diffusion rate J rises with the diffusion coefficient D, surface area A and concentration difference ΔC, and falls as membrane thickness Δx increases."},{"type":"definition","term":"Facilitated diffusion","definition":"Carrier-mediated movement down a concentration gradient. The carrier protein binds the substance and changes shape to release it on the other side. Glucose entry through GLUT transporters is the classic example."},{"type":"callout","variant":"exam","title":"Carrier-mediated transport shows saturation","text":"Because the number of carriers is limited, facilitated diffusion reaches a maximum rate (V~max~) as concentration rises. Simple diffusion does not saturate. Carriers also show **specificity** and **competition** between similar molecules."}]},{"id":"active","title":"Active transport","kind":"mechanisms","depth":"detailed","preview":false,"blocks":[{"type":"paragraph","text":"Active transport moves substances **against** their electrochemical gradient. It needs energy, either directly from ATP or indirectly from an ion gradient that ATP created."},{"type":"heading","level":3,"text":"Primary active transport"},{"type":"paragraph","text":"The carrier itself hydrolyses ATP. The Na^+^/K^+^ ATPase pumps **3 Na^+^ out** and **2 K^+^ in** for each ATP used. Because more positive charge leaves than enters, the pump is *electrogenic*."},{"type":"heading","level":3,"text":"Secondary active transport"},{"type":"paragraph","text":"Energy stored in the Na^+^ gradient (created by the Na^+^/K^+^ ATPase) drives another substance uphill."},{"type":"table","headers":["Type","Direction","Example"],"rows":[["Co-transport (symport)","Both substances move the same way","SGLT1: Na⁺ and glucose into intestinal cells"],["Counter-transport (antiport)","Substances move in opposite directions","Na⁺/Ca²⁺ exchanger removing Ca²⁺ from cardiac cells"]]},{"type":"callout","variant":"mistake","title":"Secondary active transport still depends on ATP","text":"It does not use ATP directly, but if the Na^+^/K^+^ ATPase stops (for example in severe hypoxia), the Na^+^ gradient runs down and secondary active transport fails too."}]},{"id":"vesicular","title":"Vesicular transport","kind":"step-by-step","depth":"detailed","preview":false,"blocks":[{"type":"list","ordered":false,"items":["**Endocytosis** brings material in by folding the membrane around it: phagocytosis (particles), pinocytosis (fluid) and receptor-mediated endocytosis (specific molecules such as LDL).","**Exocytosis** releases vesicle contents, for example neurotransmitters and hormones."]}]},{"id":"summary","title":"Quick revision summary","kind":"summary","depth":"exam","preview":false,"blocks":[{"type":"table","headers":["Mechanism","Energy","Carrier","Saturates?"],"rows":[["Simple diffusion","None","No","No"],["Facilitated diffusion","None","Yes","Yes"],["Primary active","ATP directly","Yes (pump)","Yes"],["Secondary active","Ion gradient","Yes","Yes"]]},{"type":"mcq","question":"Glucose absorption by SGLT1 in the small intestine is an example of:","options":["Simple diffusion","Facilitated diffusion","Primary active transport","Secondary active transport"],"answerIndex":3,"explanation":"SGLT1 couples glucose entry to Na^+^ moving down its gradient into the cell. The gradient is maintained by the Na^+^/K^+^ ATPase, so this is secondary active co-transport."}]}]}'::jsonb, 'Initial sample version') on conflict (id) do nothing;
insert into public.content_versions (id, content_item_id, version_number, structured_content, change_summary) values ('40000000-0000-4000-8000-000000000003', '30000000-0000-4000-8000-000000000003', 1, '{"schemaVersion":1,"subtitle":"Ten reactions, three control points, one clear story","overview":"Glycolysis splits one glucose molecule into two pyruvate molecules in the cytosol. It works with or without oxygen and gives a small but fast yield of ATP.","learningObjectives":["Outline the ten steps of glycolysis in order.","Identify the three irreversible steps and their regulation.","Calculate the net ATP and NADH yield per glucose.","Explain why red blood cells depend on glycolysis.","Relate enzyme defects and poisons to their clinical effects."],"prerequisites":["Structure of glucose","Role of ATP and NAD⁺ as cofactors"],"references":[{"id":"lehninger","citation":"Nelson DL, Cox MM. Lehninger Principles of Biochemistry. W. H. Freeman / Macmillan."},{"id":"harper","citation":"Rodwell VW, et al. Harper''s Illustrated Biochemistry. McGraw Hill."}],"sections":[{"id":"overview","title":"Overview","kind":"overview","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"Glycolysis happens in the **cytosol** of every cell. Think of it in two halves: an *investment phase* that spends 2 ATP to prime and split glucose, and a *payoff phase* that earns 4 ATP and 2 NADH."},{"type":"equation","latex":"\\text{Glucose} + 2\\,\\text{NAD}^+ + 2\\,\\text{ADP} + 2\\,\\text{P}_i \\rightarrow 2\\,\\text{Pyruvate} + 2\\,\\text{NADH} + 2\\,\\text{H}^+ + 2\\,\\text{ATP} + 2\\,\\text{H}_2\\text{O}","fallbackText":"Glucose + 2 NAD⁺ + 2 ADP + 2 Pᵢ → 2 Pyruvate + 2 NADH + 2 H⁺ + 2 ATP + 2 H₂O","caption":"Net equation of glycolysis"}]},{"id":"why","title":"Why this topic matters","kind":"why-it-matters","depth":"basic","preview":true,"blocks":[{"type":"list","ordered":false,"items":["Red blood cells have no mitochondria, so glycolysis is their only source of ATP.","Exercising skeletal muscle relies on glycolysis when oxygen delivery cannot keep up.","Its control points explain how insulin, glucagon and energy status steer glucose use."]}]},{"id":"steps","title":"The ten steps","kind":"step-by-step","depth":"detailed","preview":false,"blocks":[{"type":"table","caption":"Irreversible steps are marked ✱","headers":["#","Reaction","Enzyme","Note"],"rows":[["1 ✱","Glucose → glucose-6-phosphate","Hexokinase (glucokinase in liver and β cells)","Uses 1 ATP"],["2","Glucose-6-phosphate → fructose-6-phosphate","Phosphoglucose isomerase",""],["3 ✱","Fructose-6-phosphate → fructose-1,6-bisphosphate","Phosphofructokinase-1 (PFK-1)","Uses 1 ATP; committed, rate-limiting step"],["4","Fructose-1,6-bisphosphate → DHAP + glyceraldehyde-3-phosphate","Aldolase","6-carbon sugar split into two 3-carbon sugars"],["5","DHAP ⇌ glyceraldehyde-3-phosphate","Triose phosphate isomerase","From here, everything happens twice per glucose"],["6","Glyceraldehyde-3-phosphate → 1,3-bisphosphoglycerate","Glyceraldehyde-3-phosphate dehydrogenase","Produces NADH; uses inorganic phosphate"],["7","1,3-bisphosphoglycerate → 3-phosphoglycerate","Phosphoglycerate kinase","Substrate-level phosphorylation: 1 ATP"],["8","3-phosphoglycerate → 2-phosphoglycerate","Phosphoglycerate mutase",""],["9","2-phosphoglycerate → phosphoenolpyruvate","Enolase","Inhibited by fluoride"],["10 ✱","Phosphoenolpyruvate → pyruvate","Pyruvate kinase","Substrate-level phosphorylation: 1 ATP"]]},{"type":"diagram","title":"The pathway at a glance","layout":"flow","steps":[{"label":"Glucose","detail":"Hexokinase, −1 ATP"},{"label":"Fructose-1,6-bisphosphate","detail":"PFK-1, −1 ATP"},{"label":"2 × Glyceraldehyde-3-phosphate","detail":"Aldolase + TPI"},{"label":"2 × 1,3-Bisphosphoglycerate","detail":"+2 NADH"},{"label":"2 × Phosphoenolpyruvate","detail":"+2 ATP"},{"label":"2 × Pyruvate","detail":"Pyruvate kinase, +2 ATP"}]}]},{"id":"yield","title":"Energy yield","kind":"first-principles","depth":"exam","preview":false,"blocks":[{"type":"table","headers":["Phase","ATP","NADH"],"rows":[["Investment (steps 1 and 3)","−2","0"],["Payoff (steps 7 and 10, twice each)","+4","+2 (step 6, twice)"],["Net per glucose","+2","+2"]]},{"type":"callout","variant":"exam","title":"Remember the ''twice''","text":"After aldolase, each glucose gives two 3-carbon molecules, so every step from 6 to 10 happens twice. That is why the payoff phase makes 4 ATP, not 2."}]},{"id":"regulation","title":"Regulation at the irreversible steps","kind":"mechanisms","depth":"advanced","preview":false,"blocks":[{"type":"table","headers":["Enzyme","Activated by","Inhibited by"],"rows":[["Hexokinase","—","Glucose-6-phosphate (product)"],["Glucokinase (liver, β cells)","Insulin (induces synthesis)","Not inhibited by glucose-6-phosphate"],["PFK-1","AMP, fructose-2,6-bisphosphate","ATP, citrate"],["Pyruvate kinase","Fructose-1,6-bisphosphate (feed-forward)","ATP, alanine; in liver, phosphorylation after glucagon signalling"]]},{"type":"definition","term":"Hexokinase vs glucokinase","definition":"Hexokinase has a low Km (high affinity) and is inhibited by its product, so it works well at normal glucose levels in most tissues. Glucokinase has a high Km (low affinity) and is not inhibited by glucose-6-phosphate, so the liver and pancreatic β cells keep taking up glucose when blood glucose is high.","simplified":"Hexokinase grabs glucose even when there is little around. Glucokinase only gets busy when there is plenty, which makes it a good glucose sensor."}]},{"id":"anaerobic","title":"When oxygen is limited","kind":"clinical-relevance","depth":"clinical","preview":false,"blocks":[{"type":"paragraph","text":"Step 6 needs NAD^+^. Without oxygen, mitochondria cannot reoxidise NADH, so lactate dehydrogenase converts pyruvate to **lactate** and regenerates NAD^+^ in the cytosol. This keeps glycolysis running."},{"type":"callout","variant":"clinical","title":"Clinical links","text":"**Pyruvate kinase deficiency** reduces ATP production in red cells and causes haemolytic anaemia. **Fluoride** inhibits enolase, which is why fluoride tubes are used to stop glycolysis in blood glucose samples. **Arsenate** competes with phosphate at step 6, so the ATP normally made at step 7 is lost."},{"type":"callout","variant":"note","title":"Red cells and 2,3-BPG","text":"In red blood cells, some 1,3-bisphosphoglycerate is diverted to 2,3-bisphosphoglycerate (the Rapoport–Luebering shunt). 2,3-BPG lowers haemoglobin''s affinity for oxygen and helps unload O~2~ in tissues, at the cost of the ATP from step 7."}]},{"id":"mnemonics","title":"Mnemonic","kind":"mnemonics","depth":"exam","preview":false,"blocks":[{"type":"callout","variant":"mnemonic","title":"Irreversible steps: \"1, 3, 10\"","text":"Steps **1** (hexokinase), **3** (PFK-1) and **10** (pyruvate kinase) are the one-way steps. Gluconeogenesis needs separate enzymes to bypass exactly these three."}]},{"id":"mcqs","title":"Practice MCQs","kind":"practice-mcqs","depth":"exam","preview":false,"blocks":[{"type":"mcq","question":"Which enzyme catalyses the committed, rate-limiting step of glycolysis?","options":["Hexokinase","Phosphofructokinase-1","Aldolase","Pyruvate kinase"],"answerIndex":1,"explanation":"PFK-1 converts fructose-6-phosphate to fructose-1,6-bisphosphate. Once this step happens the molecule is committed to glycolysis, and PFK-1 is the main point of regulation."},{"type":"mcq","question":"What is the net ATP yield of glycolysis from one molecule of glucose?","options":["1","2","4","36"],"answerIndex":1,"explanation":"4 ATP are produced in the payoff phase but 2 are spent in the investment phase, so the net yield is 2 ATP."},{"type":"mcq","question":"Blood for glucose estimation is collected in fluoride tubes because fluoride inhibits:","options":["Hexokinase","Glyceraldehyde-3-phosphate dehydrogenase","Enolase","Lactate dehydrogenase"],"answerIndex":2,"explanation":"Fluoride inhibits enolase. This stops glycolysis in the cells of the sample, so the glucose concentration does not fall before analysis."}]},{"id":"summary","title":"Quick revision summary","kind":"summary","depth":"exam","preview":false,"blocks":[{"type":"list","ordered":false,"items":["Cytosolic, oxygen-independent pathway: glucose → 2 pyruvate.","Net yield: 2 ATP and 2 NADH per glucose.","Irreversible steps: hexokinase/glucokinase, PFK-1 (rate-limiting), pyruvate kinase.","Without O~2~, pyruvate → lactate regenerates NAD^+^.","RBCs rely entirely on glycolysis; PK deficiency causes haemolytic anaemia."]}]}]}'::jsonb, 'Initial sample version') on conflict (id) do nothing;
insert into public.content_versions (id, content_item_id, version_number, structured_content, change_summary) values ('40000000-0000-4000-8000-000000000004', '30000000-0000-4000-8000-000000000004', 1, '{"schemaVersion":1,"subtitle":"Why the inside of a cell is negative, explained without hand-waving","overview":"Every living cell has a voltage across its membrane, with the inside negative relative to the outside. In nerve and muscle this resting membrane potential is the starting point for every action potential.","learningObjectives":["Define the resting membrane potential and give typical values.","Explain why K⁺ is the main determinant of the resting potential.","Use the Nernst equation to calculate an equilibrium potential.","Describe the role of the Na⁺/K⁺ ATPase.","Predict the effect of changes in plasma K⁺ on excitability."],"prerequisites":["Diffusion and concentration gradients","Ion channels","The Na⁺/K⁺ ATPase"],"references":[{"id":"guyton","citation":"Hall JE, Hall ME. Guyton and Hall Textbook of Medical Physiology. Elsevier."},{"id":"ganong","citation":"Barrett KE, et al. Ganong''s Review of Medical Physiology. McGraw Hill."}],"sections":[{"id":"overview","title":"Overview","kind":"overview","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"The resting membrane potential (RMP) is the potential difference across the membrane of a cell at rest, measured inside relative to outside. Typical values are around **−70 mV** in many neurons and about **−90 mV** in skeletal muscle and large nerve fibres."},{"type":"explainer","technical":"The RMP arises mainly because the resting membrane is far more permeable to K⁺ than to Na⁺, so K⁺ diffusing out of the cell down its concentration gradient leaves behind unbalanced negative charge.","simplified":"Potassium leaks out of the cell much more easily than sodium leaks in. Each K⁺ that leaves takes a positive charge with it, so the inside ends up negative."}]},{"id":"gradients","title":"The ion gradients","kind":"first-principles","depth":"basic","preview":true,"blocks":[{"type":"table","caption":"Approximate concentrations in mammalian nerve (mmol/L); values vary between sources","headers":["Ion","Outside","Inside"],"rows":[["Na⁺","142","14"],["K⁺","4","140"],["Cl⁻","~105","~5–10"]]},{"type":"paragraph","text":"The Na^+^/K^+^ ATPase builds and maintains these gradients by moving 3 Na^+^ out and 2 K^+^ in for each ATP."}]},{"id":"nernst","title":"The Nernst equation","kind":"mechanisms","depth":"detailed","preview":false,"blocks":[{"type":"paragraph","text":"For a single ion, the **equilibrium potential** is the voltage at which the electrical force exactly balances the concentration gradient, so there is no net movement of that ion."},{"type":"equation","latex":"E_{\\text{ion}} = \\frac{61.5}{z}\\,\\log_{10}\\frac{[\\text{ion}]_{\\text{out}}}{[\\text{ion}]_{\\text{in}}}\\ \\text{mV}","fallbackText":"E(ion) = (61.5 / z) × log₁₀([ion]out / [ion]in) mV, at 37 °C","caption":"Simplified Nernst equation at body temperature; z is the charge of the ion."},{"type":"table","headers":["Ion","Calculation","Equilibrium potential"],"rows":[["K⁺","61.5 × log₁₀(4/140)","≈ −95 mV"],["Na⁺","61.5 × log₁₀(142/14)","≈ +62 mV"]]},{"type":"callout","variant":"exam","title":"Why the RMP is close to, but not equal to, E(K⁺)","text":"At rest the membrane is mostly permeable to K^+^, so the RMP sits near the K^+^ equilibrium potential. A small Na^+^ permeability pulls it slightly towards E(Na^+^), which is why a typical neuron rests at about −70 mV rather than −95 mV."},{"type":"equation","latex":"V_m = 61.5\\,\\log_{10}\\frac{P_K[K^+]_o + P_{Na}[Na^+]_o + P_{Cl}[Cl^-]_i}{P_K[K^+]_i + P_{Na}[Na^+]_i + P_{Cl}[Cl^-]_o}","fallbackText":"Vm = 61.5 × log₁₀((PK[K⁺]o + PNa[Na⁺]o + PCl[Cl⁻]i) / (PK[K⁺]i + PNa[Na⁺]i + PCl[Cl⁻]o))","caption":"Goldman–Hodgkin–Katz equation: each ion contributes in proportion to its permeability (P). Note that Cl⁻ is inverted because of its negative charge."}]},{"id":"pump","title":"What the Na⁺/K⁺ ATPase really does","kind":"misconceptions","depth":"mistake","preview":false,"blocks":[{"type":"callout","variant":"mistake","title":"\"The pump creates the resting potential\"","text":"The pump is electrogenic and contributes only a few millivolts directly. Its main role is to **maintain the concentration gradients**. The potential itself comes from ions diffusing through leak channels."},{"type":"callout","variant":"note","title":"Very few ions move","text":"Only a tiny fraction of the K^+^ inside the cell needs to cross the membrane to set up the resting potential. Bulk concentrations inside and outside are essentially unchanged."}]},{"id":"clinical","title":"Clinical relevance: plasma potassium","kind":"clinical-relevance","depth":"clinical","preview":false,"blocks":[{"type":"table","headers":["Change","Effect on E(K⁺) and RMP","Consequence"],"rows":[["Hyperkalaemia (↑ plasma K⁺)","Smaller K⁺ gradient; RMP less negative (depolarised)","Excitability rises at first; sustained depolarisation inactivates Na⁺ channels. Risk of dangerous cardiac arrhythmias."],["Hypokalaemia (↓ plasma K⁺)","Larger K⁺ gradient; RMP more negative (hyperpolarised)","Cells are harder to excite; muscle weakness and arrhythmias can occur."]]},{"type":"callout","variant":"clinical","title":"Caution","text":"This note explains mechanisms for learning. Recognition and management of potassium disorders must follow current clinical guidelines and supervision."}]},{"id":"questions","title":"Practice questions","kind":"practice-mcqs","depth":"exam","preview":false,"blocks":[{"type":"mcq","question":"The resting membrane potential of a neuron is closest to the equilibrium potential of which ion?","options":["Na⁺","K⁺","Ca²⁺","Cl⁻ in every neuron"],"answerIndex":1,"explanation":"At rest, K^+^ permeability dominates, so the membrane potential lies close to E(K^+^)."},{"type":"question","kind":"short-answer","question":"Why does a rise in extracellular K⁺ depolarise the membrane?","answer":"Raising [K⁺] outside reduces the concentration gradient driving K⁺ out of the cell. By the Nernst equation, E(K⁺) becomes less negative, and because the resting membrane is mainly permeable to K⁺, the RMP moves with it."},{"type":"question","kind":"oral","question":"If you blocked the Na⁺/K⁺ ATPase, would the resting potential disappear immediately?","answer":"No. The small direct electrogenic contribution would be lost at once, but the gradients only run down slowly, so the RMP declines gradually as the gradients dissipate."}]},{"id":"summary","title":"Quick revision summary","kind":"summary","depth":"exam","preview":false,"blocks":[{"type":"list","ordered":false,"items":["RMP ≈ −70 mV (many neurons) to −90 mV (skeletal muscle, large fibres).","Main cause: K⁺ efflux through leak channels; resting membrane is far more permeable to K⁺ than Na⁺.","Nernst: E(K⁺) ≈ −95 mV, E(Na⁺) ≈ +62 mV with typical concentrations.","Na⁺/K⁺ ATPase: 3 Na⁺ out, 2 K⁺ in; maintains gradients, small direct contribution.","Hyperkalaemia depolarises; hypokalaemia hyperpolarises."]}]}]}'::jsonb, 'Initial sample version') on conflict (id) do nothing;
insert into public.content_versions (id, content_item_id, version_number, structured_content, change_summary) values ('40000000-0000-4000-8000-000000000005', '30000000-0000-4000-8000-000000000005', 1, '{"schemaVersion":1,"subtitle":"Roots to branches, with the injuries that examiners ask about","overview":"The brachial plexus is the network of nerves that supplies the upper limb. Once you see it as five stages, it stops being a tangle and becomes a predictable map.","learningObjectives":["Name the roots that form the brachial plexus.","Describe how roots form trunks, divisions and cords.","List the five terminal branches and their root values.","Explain the deformities in Erb''s and Klumpke''s palsy."],"prerequisites":["Spinal nerves and ventral rami","Axillary artery and its parts"],"references":[{"id":"grays-students","citation":"Drake RL, Vogl AW, Mitchell AWM. Gray''s Anatomy for Students. Elsevier."},{"id":"moore","citation":"Moore KL, Dalley AF, Agur AMR. Clinically Oriented Anatomy. Wolters Kluwer."}],"sections":[{"id":"overview","title":"Overview","kind":"overview","depth":"basic","preview":true,"blocks":[{"type":"paragraph","text":"The plexus is formed by the **ventral rami of C5, C6, C7, C8 and T1**. It begins in the neck, passes over the first rib and enters the axilla, where it surrounds the axillary artery."},{"type":"diagram","title":"Five stages","layout":"flow","steps":[{"label":"Roots (5)","detail":"C5, C6, C7, C8, T1"},{"label":"Trunks (3)","detail":"Upper, middle, lower"},{"label":"Divisions (6)","detail":"Anterior and posterior from each trunk"},{"label":"Cords (3)","detail":"Lateral, medial, posterior"},{"label":"Terminal branches (5)","detail":"Musculocutaneous, median, ulnar, axillary, radial"}]},{"type":"callout","variant":"mnemonic","title":"\"Read That Damn Cadaver Book\"","text":"**R**oots, **T**runks, **D**ivisions, **C**ords, **B**ranches."}]},{"id":"formation","title":"How the parts join","kind":"step-by-step","depth":"detailed","preview":false,"blocks":[{"type":"table","headers":["Part","Formed from"],"rows":[["Upper trunk","C5 + C6"],["Middle trunk","C7"],["Lower trunk","C8 + T1"],["Lateral cord","Anterior divisions of upper and middle trunks (C5–C7)"],["Medial cord","Anterior division of lower trunk (C8–T1)"],["Posterior cord","Posterior divisions of all three trunks (C5–T1)"]]},{"type":"callout","variant":"tip","title":"Why the cords have these names","text":"The cords are named by their position relative to the **second part of the axillary artery**: lateral, medial and posterior to it."},{"type":"callout","variant":"exam","title":"Anterior vs posterior divisions","text":"Anterior divisions supply the flexor (anterior) compartments; posterior divisions supply the extensor (posterior) compartments. That is why the posterior cord gives the radial and axillary nerves."}]},{"id":"branches","title":"Terminal branches","kind":"comparisons","depth":"detailed","preview":false,"blocks":[{"type":"table","headers":["Nerve","Cord","Usual root value","Main motor territory"],"rows":[["Musculocutaneous","Lateral","C5–C7","Anterior compartment of the arm (biceps, brachialis, coracobrachialis)"],["Median","Lateral + medial","C6–T1 (often C5–T1)","Most forearm flexors, thenar muscles, lateral two lumbricals"],["Ulnar","Medial","C8–T1 (often with C7)","Flexor carpi ulnaris, medial half of FDP, most intrinsic hand muscles"],["Axillary","Posterior","C5–C6","Deltoid, teres minor"],["Radial","Posterior","C5–T1","Extensors of the arm and forearm"]]},{"type":"heading","level":3,"text":"Important branches before the cords"},{"type":"list","ordered":false,"items":["**Dorsal scapular nerve** (C5 root): rhomboids and levator scapulae.","**Long thoracic nerve** (C5–C7 roots): serratus anterior. Injury causes a *winged scapula*.","**Suprascapular nerve** (upper trunk, C5–C6): supraspinatus and infraspinatus."]}]},{"id":"clinical","title":"Clinical relevance","kind":"clinical-relevance","depth":"clinical","preview":false,"blocks":[{"type":"table","headers":["Injury","Level","Typical cause","Classic picture"],"rows":[["Erb''s palsy","Upper trunk (C5–C6)","Excessive separation of head and shoulder, e.g. difficult delivery or a fall on the shoulder","\"Waiter''s tip\": arm adducted and medially rotated, elbow extended, forearm pronated"],["Klumpke''s palsy","Lower trunk (C8–T1)","Sudden upward pull of the arm, e.g. grabbing a support during a fall","Claw hand from paralysis of intrinsic hand muscles; Horner syndrome if T1 sympathetic fibres are involved"]]},{"type":"callout","variant":"clinical","title":"Thinking clinically","text":"Work out the level from the pattern of weakness and sensory loss, then check it against the root values above. This approach works better than memorising each injury separately."}]},{"id":"questions","title":"Practice questions","kind":"practice-mcqs","depth":"exam","preview":false,"blocks":[{"type":"mcq","question":"Which cord of the brachial plexus gives rise to the axillary nerve?","options":["Lateral cord","Medial cord","Posterior cord","Upper trunk"],"answerIndex":2,"explanation":"The posterior cord, formed from all three posterior divisions, gives the axillary and radial nerves."},{"type":"mcq","question":"A newborn after a difficult delivery holds the arm adducted, medially rotated with the forearm pronated. Which part is injured?","options":["Upper trunk (C5–C6)","Middle trunk (C7)","Lower trunk (C8–T1)","Posterior cord"],"answerIndex":0,"explanation":"This is the \"waiter''s tip\" position of Erb''s palsy, caused by injury to the upper trunk (C5–C6) affecting the abductors and lateral rotators of the shoulder and the flexors of the elbow."},{"type":"question","kind":"oral","question":"Why does injury to the long thoracic nerve cause winging of the scapula?","answer":"The long thoracic nerve supplies serratus anterior, which holds the medial border of the scapula against the chest wall. When it is paralysed, the medial border lifts away from the thorax, especially when pushing against resistance."}]},{"id":"summary","title":"Quick revision summary","kind":"summary","depth":"exam","preview":false,"blocks":[{"type":"list","ordered":false,"items":["Ventral rami C5–T1 → 3 trunks → 6 divisions → 3 cords → 5 terminal branches.","Cords are named relative to the 2nd part of the axillary artery.","Posterior cord → axillary and radial nerves.","Erb''s palsy = upper trunk, waiter''s tip. Klumpke''s palsy = lower trunk, claw hand ± Horner syndrome."]}]}]}'::jsonb, 'Initial sample version') on conflict (id) do nothing;
insert into public.plans (id, name, slug, description, price_minor_units, currency, billing_interval, entitlements, active) values ('50000000-0000-4000-8000-000000000001', 'StudySimplify Plus', 'plus-monthly', 'Access to all subscription-eligible premium notes while your subscription is active.', 24900, 'INR', 'month', '{"scope":"subscription_eligible","practice_questions":true}'::jsonb, false) on conflict (id) do nothing;
